from itertools import combinations


def skeleton(nodes, indep, max_k=3):
    adj = {x: set(nodes) - {x} for x in nodes}
    sepset = {}
    for k in range(max_k + 1):
        for x in nodes:
            for y in list(adj[x]):
                others = adj[x] - {y}
                if len(others) < k:
                    continue
                for s in combinations(sorted(others), k):
                    if indep(x, y, set(s)):
                        adj[x].discard(y)
                        adj[y].discard(x)
                        sepset[(x, y)] = sepset[(y, x)] = set(s)
                        break
    return adj, sepset

def add_item(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items


